class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def insert(head, x):
    new_node = Node(x)
    if head is None:
        return new_node
    current = head
    while current.next is not None:
        current = current.next
    current.next = new_node
    return head

def delete_all(head, x):
    while head is not None and head.data == x:
        head = head.next
    current = head
    while current is not None and current.next is not None:
        if current.next.data == x:
            current.next = current.next.next
        else:
            current = current.next
    return head

def reverse(head):
    prev = None
    current = head
    while current is not None:
        next_node = current.next
        current.next = prev
        prev = current
        current = next_node
    return prev

def print_list(head):
    result = []
    while head is not None:
        result.append(str(head.data))
        head = head.next
    if len(result) == 0:
        print("EMPTY")
    else:
        print(" ".join(result))

def main():
    import sys
    input = sys.stdin.read().splitlines()
    Q = int(input[0])
    head = None
    for i in range(1, Q + 1):
        parts = input[i].split()
        if parts[0] == "INSERT":
            x = int(parts[1])
            head = insert(head, x)
        elif parts[0] == "DELETE":
            x = int(parts[1])
            head = delete_all(head, x)
        elif parts[0] == "REVERSE":
            head = reverse(head)
    print_list(head)

if __name__ == "__main__":
    main()
